select coalesce(maybe_name, 'x') as a, coalesce(maybe_name, name) as b, ifnull(maybe_n, 0) as c, coalesce(maybe_name, null) as d, coalesce(maybe_name, maybe_day) as e, if(n > 1, 'a', null) as f, if(n > 1, 'a', 'b') as g, if(maybe_n, name, name) as h, case when n = 1 then 'a' else 'b' end as i, case when n = 1 then 'a' end as j, case n when 1 then name else body end as k, nullif(n, 1) as l, nullif(n, 2) as m, greatest(n, 1) as o, greatest(n, maybe_n) as p, least(name, 'a') as q, coalesce(maybe_n, maybe_n, n) as r, ifnull(name, maybe_name) as s, ifnull(maybe_name, maybe_name) as u, case when maybe_n is null then 0 else maybe_n end as v, coalesce(nullif(n, 1), 0) as w, if(maybe_n is null, 0, maybe_n) as x, elt(1, name) as z, coalesce(maybe_day, day) as aa, ifnull(maybe_doc, doc) as ab, coalesce(null, 1) as ac, coalesce(null, null) as ad, greatest(day, at) as ae, least(1, null) as af, ifnull(null, name) as ag, case when n = 1 then null else n end as ah from t
